int32_t flowc_ast_enum_of_const(AstArena arena, uint8_t* src, int32_t ns, int32_t ne) {
  int32_t j = 0;
  while (j < (arena).len) {
  if (((arena).nodes[j]).kind == AST_ENUM) {
  int32_t es = ((arena).nodes[j]).name_start;
  int32_t el = (((arena).nodes[j]).name_end - es);
  if ((ne - ns) > (el + 1) && src[(ns + el)] == 95) {
  int32_t same = 1;
  int32_t i = 0;
  while (i < el && same == 1) {
  if (src[(ns + i)] != src[(es + i)]) {
  same = 0;
}
  i = (i + 1);
}
  if (same == 1) {
  int32_t v = ((arena).nodes[j]).a;
  while (v != AST_NONE) {
  int32_t vs = ((arena).nodes[v]).name_start;
  int32_t vl = (((arena).nodes[v]).name_end - vs);
  if ((ne - ns) == ((el + 1) + vl)) {
  int32_t k = 0;
  int32_t vsame = 1;
  while (k < vl && vsame == 1) {
  if (src[(((ns + el) + 1) + k)] != src[(vs + k)]) {
  vsame = 0;
}
  k = (k + 1);
}
  if (vsame == 1) {
  return j;
}
}
  v = ((arena).nodes[v]).next;
}
}
}
}
  j = (j + 1);
}
  return AST_NONE;
}

const char* flowc_ast_unsupported_label(int32_t kind) {
  if (kind == AST_THEOREM) {
  return "theorem";
}
  if (kind == AST_ASSUME) {
  return "assume";
}
  if (kind == AST_THEREFORE) {
  return "therefore";
}
  if (kind == AST_CLAIM_REF) {
  return "claim reference";
}
  if (kind == AST_FLOW_DECL || kind == AST_FLOW_ITEM) {
  return "flow block";
}
  if (kind == AST_LAYOUT) {
  return "ui layout block";
}
  if (kind == AST_PIPE_BLOCK) {
  return "flow stage parameters `Name { p: v }`";
}
  if (kind == AST_EFFECT_ROW) {
  return "effect row (with ...)";
}
  if (kind == AST_MATCH_ARM_EXT) {
  return "match arm with an or-pattern, guard or nested pattern";
}
  if (kind == AST_FIXED_ARRAY_TYPE) {
  return "array type [T; N]";
}
  if (kind == AST_CAPABILITY_TYPE) {
  return "capability type";
}
  if (kind == AST_TRY) {
  return "? operator";
}
  if (kind == AST_VECTOR_LIT) {
  return "vector literal <...>";
}
  if (kind == AST_SORT_BY) {
  return "sort by keys / with entropy / order";
}
  if (kind == AST_MODULE) {
  return "module block";
}
  if (kind == AST_RECORD_UPDATE) {
  return "record update Name { ..base }";
}
  return "";
}

