  fb_puts(b, " + __dt_ns; let mut __every_");
  fb_put_int(b, k);
  fb_puts(b, "_n: i64 = 0; while ");
  fb_puts(b, a);
  fb_puts(b, " >= ");
  fb_put_i64(b, (c[0]).ey_ns[v]);
  fb_puts(b, " && __every_");
  fb_put_int(b, k);
  fb_puts(b, "_n < 1024 { ");
