int32_t flowc_resolve_copy_cstr(const char* s, uint8_t* dst, int32_t cap) {
  uint8_t* p = (uint8_t*)(s);
  int32_t n = (int32_t)(strlen(s));
  if ((n + 1) > cap) {
  return (0 - 1);
}
  int32_t i = 0;
  while (i < n) {
  dst[i] = p[i];
  i = (i + 1);
}
  dst[n] = 0;
  return n;
}

int32_t flowc_resolve_cstr_eq(uint8_t* a, uint8_t* b) {
  int32_t i = 0;
  while (i < 4096) {
  int32_t ca = a[i];
  int32_t cb = b[i];
  if (ca != cb) {
  return 0;
}
  if (ca == 0) {
  return 1;
}
  i = (i + 1);
}
  return 0;
}

int32_t flowc_resolve_find_path(uint8_t* store, int32_t n, int32_t row_cap, uint8_t* path) {
  int32_t i = 0;
  while (i < n) {
  uint8_t* slot = (uint8_t*)((store + (i * row_cap)));
  if (flowc_resolve_cstr_eq(slot, path) == 1) {
  return i;
}
  i = (i + 1);
}
  return (0 - 1);
}

int32_t flowc_expand_stages_in_place(uint8_t* src, int32_t n, int32_t cap, int32_t stages) {
  int32_t m = n;
  if (m >= 0 && (stages & 8) != 0) {
  m = flowc_shader_expand_in_place(src, m, cap);
}
  if (m >= 0 && (stages & 1) != 0) {
  m = flowc_field_expand_in_place(src, m, cap);
}
  if (m >= 0 && (stages & 2) != 0) {
  m = flowc_dynamics_expand_in_place(src, m, cap);
}
  if (m >= 0 && (stages & 4) != 0) {
  m = flowc_flow_blocks_expand_in_place(src, m, cap);
}
  return m;
}

int32_t flowc_expand_all_in_place(uint8_t* src, int32_t n, int32_t cap) {
  int32_t m = flowc_expand_stages_in_place(src, n, cap, 15);
  if (m < 0) {
  return m;
}
  int32_t m2 = flowc_impl_expand_in_place(src, m, cap);
  if (m2 < 0) {
  return m2;
}
  return flowc_mono_lit_expand_in_place(src, m2, cap);
}

int32_t flowc_impl_is_ident(int32_t c) {
  if (c >= 97 && c <= 122 || c >= 65 && c <= 90 || c >= 48 && c <= 57 || c == 95) {
  return 1;
}
  return 0;
}

int32_t flowc_impl_skip_ws(uint8_t* src, int32_t i, int32_t n) {
  int32_t k = i;
  while (k < n && (src[k] == 32 || src[k] == 9 || src[k] == 13 || src[k] == 10)) {
  k = (k + 1);
}
  return k;
}

int32_t flowc_impl_ident_end(uint8_t* src, int32_t i, int32_t n) {
  int32_t k = i;
  while (k < n && flowc_impl_is_ident((int32_t)(src[k])) == 1) {
  k = (k + 1);
}
  return k;
}

